const message = $input.first().json.message?.toLowerCase() || '';
const response = $input.first().json.response || '';

let intent = 'general';
let leadScore = 3;

if (message.includes('test ride') || message.includes('test drive') || message.includes('drive')) { intent = 'test-ride'; leadScore = 8; }
else if (message.includes('buy') || message.includes('purchase') || message.includes('price') || message.includes('cost') || message.includes('lakh')) { intent = 'purchase'; leadScore = 9; }
else if (message.includes('charg') || message.includes('battery') || message.includes('range')) { intent = 'charging'; leadScore = 5; }
else if (message.includes('service') || message.includes('repair') || message.includes('maintenance')) { intent = 'service'; leadScore = 6; }

return [{ json: { ...$input.first().json, intent, leadScore } }];

